/****************************************************************************
 * app/home_scense/doubao/music_player.h
 * 基于 nxplayer 的音乐播放器接口。
 *
 * 扫描指定目录下的 .mp3/.wav 文件, 使用 nxplayer API 播放。播放期间
 * music_player_is_playing() 返回 true, 供 session_loop 门控麦克风。
 ****************************************************************************/

#ifndef HOME_SCENSE_MUSIC_PLAYER_H
#define HOME_SCENSE_MUSIC_PLAYER_H

#include <stdbool.h>

/* 启动音乐播放: 扫描 dir 目录下的 .mp3/.wav 文件, 在独立线程中使用
 * nxplayer 播放。若已有音乐在播, 先停止再启动新一轮。
 * 返回 0 = 启动成功(文件已找到, 播放线程已创建);
 *       负值 = 无可用文件或错误。 */
int music_player_play(const char *dir, const char *device);

/* 停止当前音乐播放并释放资源。可安全重复调用。 */
void music_player_stop(void);

/* 当前是否正在播放音乐。供 session_loop 门控麦克风上传。 */
bool music_player_is_playing(void);

#endif /* HOME_SCENSE_MUSIC_PLAYER_H */

/****************************************************************************
 * app/home_scense/doubao/music_player.c
 * 基于 nxplayer API 的音乐播放器。
 *
 * 扫描指定目录下的 .mp3 / .wav 文件, 按随机顺序逐首播放。
 * nxplayer 内部用 playthread 异步推送音频到声卡, 本模块只需轮询
 * pplayer->state 判断播完再切下一首。
 *
 * 并发安全: g_playing 供 session_loop 轮询门控麦克风; music_player_stop()
 * 从任意线程调用, 通过 nxplayer_stop() 向 playthread 发 AUDIO_MSG_STOP
 * 并 join 等它退出, 不会出现 use-after-free。
 ****************************************************************************/

#include "music_player.h"
#include "doubao_config.h"

#include <nuttx/config.h>
#include <system/nxplayer.h>

#include <dirent.h>
#include <errno.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>

/* nxplayer 内部状态(在 nxplayer.c 中 #define, 这里复现以做轮询) */
#define NXPLAYER_STATE_IDLE    0
#define NXPLAYER_STATE_PLAYING 1
#define NXPLAYER_STATE_PAUSED  2

#define MUSIC_MAX_FILES        64
#define MUSIC_FILENAME_MAX     128
#define MUSIC_POLL_MS          500  /* 轮询播放状态间隔 */
#define MUSIC_THREAD_STACK     (8 * 1024)

/* ---- 全局状态(单例) ---- */

static FAR struct nxplayer_s *g_nxp;          /* nxplayer 实例, 播放期内持有 */
static pthread_t              g_thread;        /* 播放管理线程 */
static volatile bool          g_playing;       /* 正在播放(供外部轮询) */
static volatile bool          g_stop_flag;     /* 外部请求停止 */
static char                   g_dir[128];      /* 扫描目录 */
static char                   g_device[64];    /* 声卡设备路径 */

/* ---- 工具函数 ---- */

static uint64_t now_ms(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;
}

/* 检查文件名后缀是否为支持的音频格式 */
static bool is_music_file(const char *name)
{
  const char *dot = strrchr(name, '.');
  if (dot == NULL)
    {
      return false;
    }

  return strcasecmp(dot, ".mp3") == 0 ||
         strcasecmp(dot, ".wav") == 0;
}

/* Fisher-Yates 洗牌 */
static void shuffle_paths(char paths[][MUSIC_FILENAME_MAX], int n)
{
  for (int i = n - 1; i > 0; i--)
    {
      int j = rand() % (i + 1);
      char tmp[MUSIC_FILENAME_MAX];
      memcpy(tmp, paths[i], MUSIC_FILENAME_MAX);
      memcpy(paths[i], paths[j], MUSIC_FILENAME_MAX);
      memcpy(paths[j], tmp, MUSIC_FILENAME_MAX);
    }
}

/* 扫描目录, 返回找到的音频文件数量 */
static int scan_music_dir(const char *dir,
                          char paths[][MUSIC_FILENAME_MAX], int max)
{
  DIR *dp;
  struct dirent *ent;
  int count = 0;

  dp = opendir(dir);
  if (dp == NULL)
    {
      syslog(LOG_WARNING, "[music] opendir %s failed: %d\n", dir, errno);
      return 0;
    }

  while ((ent = readdir(dp)) != NULL && count < max)
    {
      if (ent->d_type != DT_REG && ent->d_type != DT_UNKNOWN)
        {
          continue;
        }

      if (!is_music_file(ent->d_name))
        {
          continue;
        }

      snprintf(paths[count], MUSIC_FILENAME_MAX, "%s/%s", dir, ent->d_name);
      count++;
    }

  closedir(dp);
  return count;
}

/* ---- 播放管理线程 ---- */

static FAR void *music_thread_func(FAR void *arg)
{
  char paths[MUSIC_MAX_FILES][MUSIC_FILENAME_MAX];
  int file_count;
  int i;

  (void)arg;

  /* 扫描音乐文件 */
  file_count = scan_music_dir(g_dir, paths, MUSIC_MAX_FILES);
  if (file_count == 0)
    {
      syslog(LOG_WARNING, "[music] no music files in %s\n", g_dir);
      g_playing = false;
      return NULL;
    }

  syslog(LOG_INFO, "[music] found %d files in %s\n", file_count, g_dir);

  /* 随机打乱播放顺序 */
  srand((unsigned)now_ms());
  shuffle_paths(paths, file_count);

  /* 创建 nxplayer 实例 */
  g_nxp = nxplayer_create();
  if (g_nxp == NULL)
    {
      syslog(LOG_ERR, "[music] nxplayer_create failed\n");
      g_playing = false;
      return NULL;
    }

  nxplayer_setdevice(g_nxp, g_device);

  /* 逐首播放 */
  for (i = 0; i < file_count && !g_stop_flag; i++)
    {
      int ret;

      syslog(LOG_INFO, "[music] playing [%d/%d]: %s\n",
             i + 1, file_count, paths[i]);

      ret = nxplayer_playfile(g_nxp, paths[i],
                              AUDIO_FMT_UNDEF, AUDIO_FMT_UNDEF);
      if (ret < 0)
        {
          syslog(LOG_ERR, "[music] playfile %s failed: %d\n",
                 paths[i], -ret);
          continue;  /* 跳过这首, 试下一首 */
        }

      /* 等待这首播完(或被 stop 打断) */
      while (!g_stop_flag && g_nxp->state != NXPLAYER_STATE_IDLE)
        {
          usleep(MUSIC_POLL_MS * 1000);
        }
    }

  /* 清理: 释放 nxplayer(crefs 从1降到0, 上下文被 free) */
  nxplayer_release(g_nxp);
  g_nxp = NULL;
  g_playing = false;

  syslog(LOG_INFO, "[music] playback finished\n");
  return NULL;
}

/* ---- 公开接口 ---- */

int music_player_play(const char *dir, const char *device)
{
  pthread_attr_t attr;
  int ret;

  if (dir == NULL || device == NULL)
    {
      return -EINVAL;
    }

  /* 若已有音乐在播, 先停掉 */
  if (g_playing)
    {
      music_player_stop();
    }

  /* 保存参数供线程使用 */
  strncpy(g_dir, dir, sizeof(g_dir) - 1);
  g_dir[sizeof(g_dir) - 1] = '\0';
  strncpy(g_device, device, sizeof(g_device) - 1);
  g_device[sizeof(g_device) - 1] = '\0';

  g_stop_flag = false;
  g_playing = true;

  ret = pthread_attr_init(&attr);
  if (ret != 0)
    {
      g_playing = false;
      return -ret;
    }

  pthread_attr_setstacksize(&attr, MUSIC_THREAD_STACK);
  ret = pthread_create(&g_thread, &attr, music_thread_func, NULL);
  pthread_attr_destroy(&attr);

  if (ret != 0)
    {
      syslog(LOG_ERR, "[music] pthread_create failed: %d\n", ret);
      g_playing = false;
      return -ret;
    }

  pthread_detach(g_thread);
  return 0;
}

void music_player_stop(void)
{
  if (!g_playing)
    {
      return;
    }

  g_stop_flag = true;

  /* nxplayer_stop 向 playthread 发 AUDIO_MSG_STOP 并 join 等它退出。
   * 播放线程随后看到 g_stop_flag 退出, 释放 nxplayer 上下文。 */
  if (g_nxp != NULL)
    {
      nxplayer_stop(g_nxp);
    }

  /* 等待播放线程退出(它会在 nxplayer_stop 返回后很快退出) */
  for (int i = 0; i < 50 && g_playing; i++)
    {
      usleep(50 * 1000);  /* 最多等 2.5s */
    }

  g_playing = false;
}

bool music_player_is_playing(void)
{
  return g_playing;
}

/****************************************************************************
 * app/home_scense/doubao/music_player.c
 * 基于 nxplayer API 的音乐播放器。
 *
 * 扫描指定目录下的 .mp3 / .wav 文件, 按随机顺序逐首播放。
 * nxplayer 内部用 playthread 异步推送音频到声卡, 本模块只需轮询
 * pplayer->state 判断播完再切下一首。
 *
 * 并发模型:
 *  - g_playing: 供 session_loop 轮询门控麦克风。
 *  - g_thread_active: 播放线程生命周期标志, 保证不会并发两个线程。
 *  - music_player_stop(): 仅置 g_stop_flag + nxplayer_stop(中断当前歌曲);
 *    nxplayer 上下文的释放由播放线程自己负责, 避免跨线程 use-after-free。
