  g_playing = false;
  g_thread_active = false;
  syslog(LOG_INFO, "[music] playback finished\n");
  return NULL;
}

/* ---- 公开接口 ---- */

int music_player_play(const char *dir, const char *device)
{
  pthread_attr_t attr;
  pthread_t tid;
  int ret;

  if (dir == NULL || device == NULL)
    {
      return -EINVAL;
    }

  /* 若已有音乐在播, 先停掉并等播放线程退出 */
  if (g_playing)
    {
      music_player_stop();
    }

  /* 等待上一轮播放线程彻底退出(防并发) */
  while (g_thread_active)
    {
      usleep(50 * 1000);
    }

  /* 保存参数供线程使用 */
  strncpy(g_dir, dir, sizeof(g_dir) - 1);
  g_dir[sizeof(g_dir) - 1] = '\0';
  strncpy(g_device, device, sizeof(g_device) - 1);
  g_device[sizeof(g_device) - 1] = '\0';

  g_stop_flag = false;
  g_playing = true;
  g_thread_active = true;

  ret = pthread_attr_init(&attr);
  if (ret != 0)
    {
      g_playing = false;
      g_thread_active = false;
      return -ret;
    }

  pthread_attr_setstacksize(&attr, MUSIC_THREAD_STACK);
  ret = pthread_create(&tid, &attr, music_thread_func, NULL);
  pthread_attr_destroy(&attr);

  if (ret != 0)
    {
      syslog(LOG_ERR, "[music] pthread_create failed: %d\n", ret);
      g_playing = false;
      g_thread_active = false;
      return -ret;
    }

  pthread_detach(tid);
  return 0;
}

void music_player_stop(void)
{
  if (!g_playing)
    {
      return;
    }

  g_stop_flag = true;

  /* nxplayer_stop 向 playthread 发 AUDIO_MSG_STOP 并 join 等它退出。
   * 返回后 nxplayer 上下文仍有效(crefs=1), 播放线程随后在轮询退出
   * 后自行调用 nxplayer_release 释放。这里只中断当前歌曲, 不碰 g_nxp
   * 的生命周期 —— 那是播放线程的职责。 */
  if (g_nxp != NULL)
    {
      nxplayer_stop(g_nxp);
    }

  /* 等播放线程退出(它在 nxplayer_stop 返回后很快就能退出循环) */
  while (g_thread_active)
    {
      usleep(50 * 1000);
    }
}

bool music_player_is_playing(void)
{
  return g_playing;
}

