/****************************************************************************
 * app/home_scense/doubao/music_player.c
 * 基于 nxplayer API 的音乐播放器。
 *
 * 播放单个音频文件(/data/music.mp3)。nxplayer 内部用 playthread 异步
 * 推送音频到声卡, 本模块轮询 pplayer->state 判断播完。
 *
 * 并发模型:
 *  - g_playing: 供 session_loop 轮询门控麦克风。
 *  - g_thread_active: 播放线程生命周期标志, 保证不会并发两个线程。
 *  - music_player_stop(): 仅置 g_stop_flag + nxplayer_stop(中断播放);
 *    nxplayer 上下文的释放由播放线程自己负责, 避免跨线程 use-after-free。
 ****************************************************************************/

#include "music_player.h"
#include "doubao_config.h"

#include <nuttx/config.h>
#include <nuttx/audio/audio.h>
#include <system/nxplayer.h>

#include <errno.h>
#include <pthread.h>
#include <stdio.h>
#include <syslog.h>
#include <unistd.h>

/* nxplayer 内部状态(在 nxplayer.c 中 #define, 这里复现以做轮询) */
#define NXPLAYER_STATE_IDLE    0
#define NXPLAYER_STATE_PLAYING 1

#define MUSIC_POLL_MS          500  /* 轮询播放状态间隔 */
#define MUSIC_THREAD_STACK     (8 * 1024)

/* ---- 全局状态(单例) ---- */

static FAR struct nxplayer_s *g_nxp;          /* nxplayer 实例, 播放期内持有 */
static volatile bool          g_playing;       /* 正在播放(供外部轮询) */
static volatile bool          g_stop_flag;     /* 外部请求停止 */
static volatile bool          g_thread_active; /* 播放线程正在运行 */
static char                   g_file[128];     /* 音频文件路径 */
static char                   g_device[64];    /* 声卡设备路径 */

/* ---- 播放线程 ---- */

static FAR void *music_thread_func(FAR void *arg)
{
  (void)arg;

  /* 创建 nxplayer 实例 */
  g_nxp = nxplayer_create();
  if (g_nxp == NULL)
    {
      syslog(LOG_ERR, "[music] nxplayer_create failed\n");
      goto out;
    }

  nxplayer_setdevice(g_nxp, g_device);

  syslog(LOG_INFO, "[music] playing: %s\n", g_file);

  if (nxplayer_playfile(g_nxp, g_file, AUDIO_FMT_UNDEF, AUDIO_FMT_UNDEF) < 0)
    {
      syslog(LOG_ERR, "[music] playfile %s failed\n", g_file);
      goto out_nxp;
    }

  /* 等待播完(或被 stop 打断)。
   * music_player_stop() 调用 nxplayer_stop() 会向 playthread 发
   * AUDIO_MSG_STOP 并 join 等它退出, 之后 state 变为 IDLE。 */
  while (!g_stop_flag && g_nxp->state != NXPLAYER_STATE_IDLE)
    {
      usleep(MUSIC_POLL_MS * 1000);
    }

out_nxp:
  nxplayer_release(g_nxp);
  g_nxp = NULL;

out:
  g_playing = false;
  g_thread_active = false;
  syslog(LOG_INFO, "[music] playback finished\n");
  return NULL;
}

/* ---- 公开接口 ---- */

int music_player_play(const char *file, const char *device)
{
  pthread_attr_t attr;
  pthread_t tid;
  int ret;

  if (file == NULL || device == NULL)
    {
      return -EINVAL;
    }

  /* 若已有音乐在播, 先停掉并等播放线程退出 */
  if (g_playing)
    {
      music_player_stop();
    }

  /* 等待上一轮播放线程彻底退出(防并发) */
  while (g_thread_active)
    {
      usleep(50 * 1000);
    }

  /* 保存参数供线程使用 */
  strncpy(g_file, file, sizeof(g_file) - 1);
  g_file[sizeof(g_file) - 1] = '\0';
  strncpy(g_device, device, sizeof(g_device) - 1);
  g_device[sizeof(g_device) - 1] = '\0';

  g_stop_flag = false;
  g_playing = true;
  g_thread_active = true;

  ret = pthread_attr_init(&attr);
  if (ret != 0)
    {
      g_playing = false;
      g_thread_active = false;
      return -ret;
    }

  pthread_attr_setstacksize(&attr, MUSIC_THREAD_STACK);
  ret = pthread_create(&tid, &attr, music_thread_func, NULL);
  pthread_attr_destroy(&attr);

  if (ret != 0)
    {
      syslog(LOG_ERR, "[music] pthread_create failed: %d\n", ret);
      g_playing = false;
      g_thread_active = false;
      return -ret;
    }

  pthread_detach(tid);
  return 0;
}

void music_player_stop(void)
{
  if (!g_playing)
    {
      return;
    }

  g_stop_flag = true;

  /* nxplayer_stop 向 playthread 发 AUDIO_MSG_STOP 并 join 等它退出。
   * 返回后 nxplayer 上下文仍有效(crefs=1), 播放线程随后在轮询退出
   * 后自行调用 nxplayer_release 释放。 */
  if (g_nxp != NULL)
    {
      nxplayer_stop(g_nxp);
    }

  /* 等播放线程退出 */
  while (g_thread_active)
    {
      usleep(50 * 1000);
    }
}

bool music_player_is_playing(void)
{
  return g_playing;
}
